                    emon.Port.BufPush(cbytes, emon.Port.CellsAt(data, i));
                    i += 1;
                }
                AsSet(cand, row, AcStatus, 0);
                AsSet(cand, row, AcType, Model.AmtJpeg());
                AsSet(cand, row, AcBstart, start);
                AsSet(cand, row, AcBlen, emon.Port.BufLen(cbytes) - start);
                AsSha(cbytes, start, emon.Port.BufLen(cbytes) - start, tmp, cand, row);
                AsSet(cand, row, AcW, w);
                AsSet(cand, row, AcH, h);
                AsSet(cand, row, AcFlags, flags);
                AsSet(cand, row, AcFrom, Model.AfmDct());
                AsSet(cand, row, AcOrigin, Model.AoEmbedded());
