        if ((ow * oh) > maxpix) {
            k = AsScaleK(ow, oh, maxpix);
            flags |= Model.AfgScaled();
            emon.Port.Bitmap pic2 = emon.Port.BitmapNew((ow + (k - 1)) / k, (oh + (k - 1)) / k, ch);
            emon.Port.Bitmap al2 = emon.Port.BitmapNew((ow + (k - 1)) / k, (oh + (k - 1)) / k, 1);
            AsScaleInto(pic, pic2, k);
            AsScaleInto(al, al2, k);
            AsPng(ws, cbytes, z, rows, tmp, rec, pic2, al2, alpha, 0);
            w = emon.Port.BitmapW(pic2);
            h = emon.Port.BitmapH(pic2);
        } else {
            bil = 0;
            if ((Pdfimage.PiGet(rec, Pdfimage.PiFBpc()) == 1) && (Pdfimage.PiGet(rec, Pdfimage.PiFClass()) == 1)) {
                bil = 1;
            }
            AsPng(ws, cbytes, z, rows, tmp, rec, pic, al, alpha, bil);
            w = ow;
            h = oh;
        }
        AsSet(cand, row, AcStatus, 0);
        AsSet(cand, row, AcType, Model.AmtPng());
        AsSet(cand, row, AcBstart, start);
        AsSet(cand, row, AcBlen, emon.Port.BufLen(cbytes) - start);
        AsSha(cbytes, start, emon.Port.BufLen(cbytes) - start, tmp, cand, row);
        AsSet(cand, row, AcW, w);
        AsSet(cand, row, AcH, h);
        AsSet(cand, row, AcFlags, flags);
        if (codec == 0) {
            AsSet(cand, row, AcFrom, AsFromChain(rec));
        }
        AsSet(cand, row, AcOrigin, Model.AoDecoded());
        return 0;
    }
    internal static int AsOverlaid(emon.Port.Cells im, emon.Port.Cells pa, emon.Port.Cells gl, int r, int page, int vx0, int vy0, int vx1, int vy1, int z) {
        // 1 when paint drawn after image row r (paths, images, glyphs that are visible and on its page) covers more than
        // `AS_OVERLAY` per mille of its visible box. Overlapping paints count twice: an over-estimate, on the side of
        // saying what the reader saw was not the image alone.
        long area = AsArea(vx0, vy0, vx1, vy1);
        long acc = (long) 0;
        int i = 0;
        int n = Evidence.ImCount(im);
        if (area <= ((long) 0)) {
            return 0;
        }
        while (i < n) {
            if ((i != r) && ((Evidence.ImGet(im, i, Evidence.MfPage()) == page) && ((Evidence.ImGet(im, i, Evidence.MfZ()) > z) && (Evidence.ImGet(im, i, Evidence.MfVis()) == 0)))) {
                acc = unchecked(acc + AsIa(vx0, vy0, vx1, vy1, Evidence.ImGet(im, i, Evidence.MfX0()), Evidence.ImGet(im, i, Evidence.MfY0()), Evidence.ImGet(im, i, Evidence.MfX1()), Evidence.ImGet(im, i, Evidence.MfY1())));
            }
            i += 1;
        }
        i = 0;
        n = emon.Port.CellsLen(pa) / 24;
        while (i < n) {
            if ((Evidence.PaGet(pa, i, 0) == page) && ((Evidence.PaGet(pa, i, Evidence.PfZ()) > z) && ((Evidence.PaGet(pa, i, Evidence.PfVis()) == 0) && ((Evidence.PaGet(pa, i, Evidence.PfFlags()) & Evidence.PgClip()) == 0)))) {
                acc = unchecked(acc + AsIa(vx0, vy0, vx1, vy1, Evidence.PaGet(pa, i, Evidence.PfX0()), Evidence.PaGet(pa, i, Evidence.PfY0()), Evidence.PaGet(pa, i, Evidence.PfX1()), Evidence.PaGet(pa, i, Evidence.PfY1())));
            }
            i += 1;
        }
        i = 0;
        n = Evidence.GlCount(gl);
        while (i < n) {
            if ((Evidence.GlGet(gl, i, 0) == page) && ((Evidence.GlGet(gl, i, Evidence.GfZ()) > z) && (Evidence.GlGet(gl, i, Evidence.GfVis()) == 0))) {
                acc = unchecked(acc + AsIa(vx0, vy0, vx1, vy1, Evidence.GlGet(gl, i, 1), Evidence.GlGet(gl, i, 2), Evidence.GlGet(gl, i, 3), Evidence.GlGet(gl, i, 4)));
            }
            i += 1;
        }
        if (unchecked(acc * ((long) 1000)) > unchecked(((long) AsOverlay) * area)) {
            return 1;
        }
        return 0;
    }
    public static int AsCollect(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells im, emon.Port.Cells pa, emon.Port.Cells gl, emon.Port.Cells pg, int maxpix, int totbytes, emon.Port.Cells cand, emon.Port.Buf cbytes, emon.Port.Cells @out, emon.Port.Cells rec, emon.Port.Cells mrec, emon.Port.Cells smp, emon.Port.Cells msmp, emon.Port.Cells data, emon.Port.Cells rows, emon.Port.Cells tmp, emon.Port.Cells ws, emon.Port.Buf z, int input, emon.Port.Cells ans, emon.Port.Cells rq, emon.Port.Buf payload, emon.Port.BitmapSet bms, emon.Port.Cells glob, emon.Port.Cells words, emon.Port.Cells hs) {
        // The asset unit (a document-level plan/fulfil unit, P6.1a):  a candidate row for every image placement that passed P3.6's checks (`images` rows `im`), with
        // its pixels made when a browser or a PNG can show them. `maxpix` is `asset-pixels`; `cbytes` holds at most twice
        // `totbytes` (`assets-bytes`) before a placement is `budget`, and at most `AS_MAXPROD` placements make pixels.
        // `out rec mrec smp msmp data rows tmp ws z glob words hs` are scratch. A codec image's pixels are the HOST's: the
        // first attempt writes a `decode-img` request for each (`rq`, with its bytes in `payload` when they are not the input's
        // own; `input` is the input's index) and answers 1; the host fulfils them and runs the unit again with `ans` and the
        // bitmaps `bms`, and the same call makes the candidates. Answers 0 (done), 1 (requests written: fulfil and run again) or
        // 12 when the source missed (stop, re-run).
        int n = Evidence.ImCount(im);
        int r = 0;
        int row = 0;
        int prod = 0;
        int page = 0;
        int bx0 = 0;
        int by0 = 0;
        int bx1 = 0;
        int by1 = 0;
        int vx0 = 0;
        int vy0 = 0;
        int vx1 = 0;
        int vy1 = 0;
        int clip = -1;
        int flags = 0;
        int ori = 0;
        int obj = 0;
        int pw = 0;
        int ph = 0;
        int f = 0;
        int rc = 0;
        int zz = 0;
        int work = 0;
        int ovl = AsOverlayWork;
        int whole = 0;
        emon.Port.CellsDrop(cand, 0);
        emon.Port.CellsDrop(hs, 0);
        emon.Port.CellsPush(hs, 0);
        while (r < n) {
            if (Evidence.ImGet(im, r, Evidence.MfVis()) == 0) {
                page = Evidence.ImGet(im, r, Evidence.MfPage());
                bx0 = Evidence.ImGet(im, r, Evidence.MfX0());
                by0 = Evidence.ImGet(im, r, Evidence.MfY0());
                bx1 = Evidence.ImGet(im, r, Evidence.MfX1());
                by1 = Evidence.ImGet(im, r, Evidence.MfY1());
                vx0 = bx0;
                vy0 = by0;
                vx1 = bx1;
                vy1 = by1;
                flags = 0;
                clip = Evidence.ImGet(im, r, Evidence.MfClip());
                if ((clip >= 0) && (clip < (emon.Port.CellsLen(pa) / 24))) {
                    if (Evidence.PaGet(pa, clip, Evidence.PfX0()) > vx0) {
                        vx0 = Evidence.PaGet(pa, clip, Evidence.PfX0());
                    }
                    if (Evidence.PaGet(pa, clip, Evidence.PfY0()) > vy0) {
                        vy0 = Evidence.PaGet(pa, clip, Evidence.PfY0());
                    }
                    if (Evidence.PaGet(pa, clip, Evidence.PfX1()) < vx1) {
                        vx1 = Evidence.PaGet(pa, clip, Evidence.PfX1());
                    }
                    if (Evidence.PaGet(pa, clip, Evidence.PfY1()) < vy1) {
                        vy1 = Evidence.PaGet(pa, clip, Evidence.PfY1());
                    }
                    if (Evidence.PaGet(pa, clip, Evidence.PfKind()) != Evidence.PaRect()) {
                        flags |= Model.AfgClipBbox();
                    }
                }
                ori = Evidence.ImGet(im, r, Evidence.MfPlacement());
                if (ori == 8) {
                    flags |= Model.AfgTransformed();
                }
                obj = Evidence.ImGet(im, r, Evidence.MfObj());
                if ((vx1 > vx0) && (vy1 > vy0) && (page >= 1) && (page <= Pdfdoc.PdPgCount(pg))) {
                    row = emon.Port.CellsLen(cand) / AsStride;
                    f = 0;
                    while (f < AsStride) {
                        emon.Port.CellsPush(cand, 0);
                        f += 1;
                    }
                    AsSet(cand, row, AcPage, page);
                    AsSet(cand, row, AcBx0, bx0);
                    AsSet(cand, row, AcBx0 + 1, by0);
                    AsSet(cand, row, AcBx0 + 2, bx1);
                    AsSet(cand, row, AcBx0 + 3, by1);
                    AsSet(cand, row, AcVx0, vx0);
                    AsSet(cand, row, AcVx0 + 1, vy0);
                    AsSet(cand, row, AcVx0 + 2, vx1);
                    AsSet(cand, row, AcVx0 + 3, vy1);
                    AsSet(cand, row, AcObj, obj);
                    AsSet(cand, row, AcFrom, Model.AfmRaw());
                    AsSet(cand, row, AcOrigin, Model.AoDecoded());
                    AsSet(cand, row, AcType, Model.AmtPng());
                    AsSet(cand, row, AcKori, -1);
                    AsSet(cand, row, AcFlags, flags);
                    pw = AsPageW(pg, page - 1);
                    ph = AsPageH(pg, page - 1);
                    if (AsIa(vx0, vy0, vx1, vy1, 0, 0, pw, ph) > ((long) 0)) {
                        whole = AsGe(AsIa(vx0, vy0, vx1, vy1, 0, 0, pw, ph), AsArea(0, 0, pw, ph), AsBig);
                    } else {
                        whole = 0;
                    }
                    if (whole == 1) {
                        AsSet(cand, row, AcStatus, Model.NzPart());
                    } else if (obj <= 0) {
                        AsSet(cand, row, AcStatus, Model.NzCodec());
                    } else if ((prod >= AsMaxprod) || ((emon.Port.BufLen(cbytes) / 2) > totbytes)) {
                        AsSet(cand, row, AcStatus, Model.NzBudget());
                    } else {
                        prod += 1;
                        rc = AsMake(src, ar, dc, a, b, st, maxpix, cand, row, obj, ori, 1, cbytes, @out, rec, mrec, smp, msmp, data, rows, tmp, ws, z, input, ans, rq, payload, bms, glob, words, hs);
                        if (rc == 12) {
                            return 12;
                        }
                        if (AsGet(cand, row, AcStatus) == 0) {
                            // the overlay check reads every later paint of the page: at most AS_OVERLAY_WORK rows in all
                            work = (n + (emon.Port.CellsLen(pa) / 24)) + Evidence.GlCount(gl);
                            if (ovl >= work) {
                                ovl -= work;
                                zz = Evidence.ImGet(im, r, Evidence.MfZ());
                                if (AsOverlaid(im, pa, gl, r, page, vx0, vy0, vx1, vy1, zz) == 1) {
                                    zz = AsGet(cand, row, AcFlags);
                                    AsSet(cand, row, AcFlags, zz | Model.AfgOverlaid());
                                }
                            }
                        }
                    }
                }
            }
            r += 1;
        }
        if (emon.Port.CellsLen(rq) > 0) {
            return 1;
        }
        return 0;
    }
    public static int AsFigureRows(emon.Port.Cells cand, emon.Port.Cells pages, emon.Port.Cells fg) {
        // The candidates that are provisional `figure`s (SPEC 10.6, until P8.1): not page-sized (under 800 per mille of its
        // page) and both sides of the visible box at least 18 pt. `fg` = [cursor 0, then the candidate rows sorted by (page,
        // top, left, row)]. Answers how many.
        int n = emon.Port.CellsLen(cand) / AsStride;
        int r = 0;
        int j = 0;
        int pw = 0;
        int ph = 0;
        int pgi = 0;
        int cnt = 0;
        int ins = 0;
        int x0 = 0;
        int y0 = 0;
        int x1 = 0;
        int y1 = 0;
        emon.Port.CellsDrop(fg, 0);
        emon.Port.CellsPush(fg, 0);
        while (r < n) {
            x0 = AsGet(cand, r, AcVx0);
            y0 = AsGet(cand, r, AcVx0 + 1);
            x1 = AsGet(cand, r, AcVx0 + 2);
            y1 = AsGet(cand, r, AcVx0 + 3);
            pgi = AsGet(cand, r, AcPage) - 1;
            if ((pgi >= 0) && (pgi < Model.PageCount(pages))) {
                pw = Model.PageW(pages, pgi);
                ph = Model.PageH(pages, pgi);
                if (((x1 - x0) >= AsFigureSide) && ((y1 - y0) >= AsFigureSide) && (AsGe(AsIa(x0, y0, x1, y1, 0, 0, pw, ph), AsArea(0, 0, pw, ph), AsBig) == 0)) {
                    // insert in order of (page, top, left, row)
                    ins = cnt + 1;
                    j = 1;
                    while (j <= cnt) {
                        int q = emon.Port.CellsAt(fg, j);
                        if ((ins == (cnt + 1)) && ((AsGet(cand, q, AcPage) > AsGet(cand, r, AcPage)) || ((AsGet(cand, q, AcPage) == AsGet(cand, r, AcPage)) && ((AsGet(cand, q, AcVx0 + 1) > y0) || ((AsGet(cand, q, AcVx0 + 1) == y0) && (AsGet(cand, q, AcVx0) > x0)))))) {
                            ins = j;
                        }
                        j += 1;
                    }
                    emon.Port.CellsPush(fg, 0);
                    j = cnt + 1;
                    while (j > ins) {
                        emon.Port.CellsSet(fg, j, emon.Port.CellsAt(fg, j - 1));
                        j -= 1;
                    }
                    emon.Port.CellsSet(fg, ins, r);
                    cnt += 1;
                }
            }
            r += 1;
        }
        return cnt;
    }
    internal static int AsFirstRegion(emon.Port.Cells nodes, emon.Port.Cells regions, int n, emon.Port.Cells box) {
        // The node's first region into box[0..5): page x0 y0 x1 y1. 0 when it has none.
        int r = Model.NodeRegionHead(nodes, n);
        if (r < 0) {
            return 0;
        }
        emon.Port.CellsSet(box, 0, Model.RegionPage(regions, r));
        emon.Port.CellsSet(box, 1, Model.RegionX0(regions, r));
        emon.Port.CellsSet(box, 2, Model.RegionY0(regions, r));
        emon.Port.CellsSet(box, 3, Model.RegionX1(regions, r));
        emon.Port.CellsSet(box, 4, Model.RegionY1(regions, r));
        return 1;
    }
    internal static int AsMatch(emon.Port.Cells cand, int page, int x0, int y0, int x1, int y1, emon.Port.Cells box) {
        // Which candidate a region is, geometrically (SPEC 10.11 steps 2-4 at `images`): box[0] the candidate row when the
        // region IS one whole image; else a negative `nz` code: -`nz-part` when it lies inside one image's visible box,
        // -`nz-composite` when it overlaps several or part of one and more, -`nz-vector` when no image is under it.
        int n = emon.Port.CellsLen(cand) / AsStride;
        long ra = AsArea(x0, y0, x1, y1);
        int r = 0;
        int hits = 0;
        int only = -1;
        long ia = (long) 0;
        long va = (long) 0;
        while (r < n) {
            if (AsGet(cand, r, AcPage) == page) {
                ia = AsIa(x0, y0, x1, y1, AsGet(cand, r, AcVx0), AsGet(cand, r, AcVx0 + 1), AsGet(cand, r, AcVx0 + 2), AsGet(cand, r, AcVx0 + 3));
                if (ia > ((long) 0)) {
                    hits += 1;
                    only = r;
                }
            }
            r += 1;
        }
        emon.Port.CellsSet(box, 0, -1);
        if (hits == 0) {
            return 0 - Model.NzVector();
        }
        if (hits > 1) {
            return 0 - Model.NzComposite();
        }
        ia = AsIa(x0, y0, x1, y1, AsGet(cand, only, AcVx0), AsGet(cand, only, AcVx0 + 1), AsGet(cand, only, AcVx0 + 2), AsGet(cand, only, AcVx0 + 3));
        va = AsArea(AsGet(cand, only, AcVx0), AsGet(cand, only, AcVx0 + 1), AsGet(cand, only, AcVx0 + 2), AsGet(cand, only, AcVx0 + 3));
        if ((AsGe(ia, ra, AsCover) == 1) && (AsGe(ia, va, AsCover) == 1)) {
            emon.Port.CellsSet(box, 0, only);
            return 0;
        }
        if (AsGe(ia, ra, AsCover) == 1) {
            return 0 - Model.NzPart();
        }
        return 0 - Model.NzComposite();
    }
    internal static int AsSetNoasset(emon.Port.Cells nodes, emon.Port.Cells attrs, int n, int reason) {
        Model.NodeSetAttrInt(nodes, attrs, n, Model.FkNoasset(), reason);
        return 0;
    }
    public static int AsRun(emon.Port.Cells nodes, emon.Port.Cells attrs, emon.Port.Cells regions, emon.Port.Cells cand, emon.Port.Buf cbytes, emon.Port.Cells assets, emon.Port.Cells uses, emon.Port.Buf abytes, int maxbytes, int totbytes, int sigs, emon.Port.Cells box) {
        // The document unit's asset stage, in node-id order, over the figures and seals of the final tree: SPEC 10.11's source
        // per node, then admission. A node with pixels gets `fk-asset` (an asset id), else `fk-noasset` (an `nz`). The Model's
        // `assets`, `uses` and `abytes` are written. `box` is 5 scratch cells. A figure made from a placement (`fk-image`
        // names its candidate row) is that image; any other is matched by where it is. Answers the number of assets.
        int nn = Model.NodeCount(nodes);
        int n = 0;
        int kind = 0;
        int sub = 0;
        int c = -1;
        int rc = 0;
        int attr = -1;
        int id = -1;
        int total = 0;
        int closed = 0;
        int blen = 0;
        int bs = 0;
        while (n < nn) {
            kind = Model.NodeKind(nodes, n);
            if ((kind == Model.NkFigure()) || (kind == Model.NkSeal())) {
                sub = Model.NodeSub(nodes, n);
                c = -1;
                rc = 0;
                if (kind == Model.NkSeal()) {
                    if (sub == Model.SlDigitalSignature()) {
                        rc = -1;
                    }
                    if (((sub == Model.SlSignature()) || (sub == Model.SlInitials())) && (sigs == 0)) {
                        AsSetNoasset(nodes, attrs, n, Model.NzWithheld());
                        rc = -1;
                    }
                }
                if (rc == 0) {
                    attr = Model.NodeAttr(nodes, attrs, n, Model.FkImage());
                    if (attr >= 0) {
                        c = Model.AttrValue(attrs, attr);
                    } else if (AsFirstRegion(nodes, regions, n, box) == 1) {
                        rc = AsMatch(cand, emon.Port.CellsAt(box, 0), emon.Port.CellsAt(box, 1), emon.Port.CellsAt(box, 2), emon.Port.CellsAt(box, 3), emon.Port.CellsAt(box, 4), box);
                        if (rc == 0) {
                            c = emon.Port.CellsAt(box, 0);
                        }
                        if (rc < 0) {
                            rc = 0 - rc;
                        }
                    } else {
                        rc = Model.NzVector();
                    }
                    if ((c < 0) && (rc > 0)) {
                        AsSetNoasset(nodes, attrs, n, rc);
                    }
                    if (c >= 0) {
                        if (AsGet(cand, c, AcStatus) != 0) {
                            AsSetNoasset(nodes, attrs, n, AsGet(cand, c, AcStatus));
                        } else {
                            blen = AsGet(cand, c, AcBlen);
                            id = Model.AssetFind(assets, blen, AsGet(cand, c, AcSha + 0), AsGet(cand, c, AcSha + 1), AsGet(cand, c, AcSha + 2), AsGet(cand, c, AcSha + 3), AsGet(cand, c, AcSha + 4), AsGet(cand, c, AcSha + 5), AsGet(cand, c, AcSha + 6), AsGet(cand, c, AcSha + 7));
                            if ((id < 0) && (blen > maxbytes)) {
                                AsSetNoasset(nodes, attrs, n, Model.NzTooLarge());
                            } else {
                                if ((id < 0) && ((closed == 1) || (blen > (totbytes - total)))) {
                                    closed = 1;
                                    AsSetNoasset(nodes, attrs, n, Model.NzBudget());
                                } else {
                                    if (id < 0) {
                                        bs = emon.Port.BufLen(abytes);
                                        emon.Port.BufAppendBlob(abytes, emon.Port.BufBlob(cbytes), AsGet(cand, c, AcBstart), AsGet(cand, c, AcBstart) + blen);
                                        total += blen;
                                        id = Model.AssetAdd(assets, AsGet(cand, c, AcType), AsGet(cand, c, AcOrigin), AsGet(cand, c, AcFrom), AsGet(cand, c, AcObj), bs, blen, AsGet(cand, c, AcW), AsGet(cand, c, AcH), 0, AsGet(cand, c, AcFlags));
                                        Model.AssetSetSha(assets, id, 0, AsGet(cand, c, AcSha + 0));
                                        Model.AssetSetSha(assets, id, 1, AsGet(cand, c, AcSha + 1));
                                        Model.AssetSetSha(assets, id, 2, AsGet(cand, c, AcSha + 2));
                                        Model.AssetSetSha(assets, id, 3, AsGet(cand, c, AcSha + 3));
                                        Model.AssetSetSha(assets, id, 4, AsGet(cand, c, AcSha + 4));
                                        Model.AssetSetSha(assets, id, 5, AsGet(cand, c, AcSha + 5));
                                        Model.AssetSetSha(assets, id, 6, AsGet(cand, c, AcSha + 6));
                                        Model.AssetSetSha(assets, id, 7, AsGet(cand, c, AcSha + 7));
                                    }
                                    Model.UseAdd(assets, uses, id, n, AsGet(cand, c, AcPage), AsGet(cand, c, AcVx0 + 0), AsGet(cand, c, AcVx0 + 1), AsGet(cand, c, AcVx0 + 2), AsGet(cand, c, AcVx0 + 3));
                                    Model.NodeSetAttrInt(nodes, attrs, n, Model.FkAsset(), id);
                                }
                            }
                        }
                    }
                }
            }
            n += 1;
        }
        return Model.AssetCount(assets);
    }
    public static int AsSettings(emon.Port.Cells nodes, emon.Port.Cells attrs, emon.Port.Cells text, int level, int dpi, int maxpix, int maxbytes, int totbytes, int sigs) {
        // The settings that go with the level, on the root (SPEC 10.11): `assets` (`images` 1, `figures` 2), `asset-dpi`,
        // `asset-pixels`, `asset-bytes`, `assets-bytes` and `asset-signatures` (`off` 0, `on` 1).
        int s = emon.Port.CellsLen(text);
        if (level == 1) {
            Model.TextAppendCp(text, 105);
            Model.TextAppendCp(text, 109);
            Model.TextAppendCp(text, 97);
            Model.TextAppendCp(text, 103);
            Model.TextAppendCp(text, 101);
            Model.TextAppendCp(text, 115);
        }
        if (level == 2) {
            Model.TextAppendCp(text, 102);
            Model.TextAppendCp(text, 105);
            Model.TextAppendCp(text, 103);
            Model.TextAppendCp(text, 117);
            Model.TextAppendCp(text, 114);
            Model.TextAppendCp(text, 101);
            Model.TextAppendCp(text, 115);
        }
        Model.NodeSetAttrText(nodes, attrs, 0, Model.FkAssets(), s, emon.Port.CellsLen(text) - s);
        Model.NodeSetAttrInt(nodes, attrs, 0, Model.FkAssetDpi(), dpi);
        Model.NodeSetAttrInt(nodes, attrs, 0, Model.FkAssetPixels(), maxpix);
        Model.NodeSetAttrInt(nodes, attrs, 0, Model.FkAssetBytes(), maxbytes);
        Model.NodeSetAttrInt(nodes, attrs, 0, Model.FkAssetsBytes(), totbytes);
        s = emon.Port.CellsLen(text);
        if (sigs == 1) {
            Model.TextAppendCp(text, 111);
            Model.TextAppendCp(text, 110);
        }
        if (sigs == 0) {
            Model.TextAppendCp(text, 111);
            Model.TextAppendCp(text, 102);
            Model.TextAppendCp(text, 102);
        }
        Model.NodeSetAttrText(nodes, attrs, 0, Model.FkAssetSignatures(), s, emon.Port.CellsLen(text) - s);
        return 0;
    }
    public static int AsPageCands(emon.Port.Cells pages, emon.Port.Cells cand) {
        // A raster input is one picture a page (a frame): each page's own image is a candidate whose status is `part` (SPEC
        // 10.11): at `images` no figure or seal of it can be that picture, and `figures` cuts from it (P8.5, `cropped`).
        int n = Model.PageCount(pages);
        int p = 0;
        int row = 0;
        int f = 0;
        emon.Port.CellsDrop(cand, 0);
        while (p < n) {
            row = emon.Port.CellsLen(cand) / AsStride;
            f = 0;
            while (f < AsStride) {
                emon.Port.CellsPush(cand, 0);
                f += 1;
            }
            AsSet(cand, row, AcPage, Model.PageNumber(pages, p));
            AsSet(cand, row, AcBx0 + 2, Model.PageW(pages, p));
            AsSet(cand, row, AcBx0 + 3, Model.PageH(pages, p));
            AsSet(cand, row, AcVx0 + 2, Model.PageW(pages, p));
            AsSet(cand, row, AcVx0 + 3, Model.PageH(pages, p));
            AsSet(cand, row, AcStatus, Model.NzPart());
            AsSet(cand, row, AcObj, -1);
            AsSet(cand, row, AcKori, -1);
            p += 1;
        }
        return n;
    }
}
